private static void deleteDirectoryOnExit(File dir) throws IOException {
    if (!dir.exists()) {
        return;
    }

    File[] files = dir.listFiles();
    if (files == null) { // null if security restricted
        throw new IOException("Failed to list contents of " + dir);
    }

