    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // If we encounter a backslash, check if it's preceded by another backslash
        if (c == '\\' && i > 0 && str.charAt(i - 1) == '\\') {
            // If it is, append the current character as is
            sb.append(c);
        } else if (c == 'n') {
            // If the character is a newline, append a newline character
            sb.append('\n');
        } else if (c == 'r') {
            // If the character is a carriage return, append a carriage return character
            sb.append('\r');
        } else if (c == 't') {
            // If the character is a tab character, append a tab character
            sb.append('\t');
        } else if (c == 'b') {
